import * as React from "react"
import { MoreHorizontal } from "lucide-react"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription,
  AlertDialogFooter, AlertDialogTitle } from "@atlas/ui-web/compositions/AlertDialog/AlertDialog"
import { Card, CardContent, CardHeader, CardTitle } from "@atlas/ui-web/compositions/Card/Card"
import { Dialog, DialogBody, DialogClose, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@atlas/ui-web/compositions/Dialog/Dialog"
import { Field } from "@atlas/ui-web/compositions/Field/Field"
import { toast } from "@atlas/ui-web/compositions/Toast/Toast"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@atlas/ui-web/patterns/DropdownMenu/DropdownMenu"
import { Avatar } from "@atlas/ui-web/primitives/Avatar/Avatar"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@atlas/ui-web/primitives/Select/Select"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@atlas/ui-web/primitives/Table/Table"

type Role = "Owner" | "Admin" | "Member"
type Member = { id: string; name: string; email: string; role: Role; pending?: boolean }

const ROLES: Role[] = ["Owner", "Admin", "Member"]

const title = { fontSize: "var(--atlas-text-h1)" }
const muted = { fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }
const initialsOf = (name: string) => name.split(" ").map((p) => p[0]).join("").slice(0, 2).toUpperCase()
const firstName = (name: string) => name.split(" ")[0]

export function MembersPage({ members, currentUserId, loading, onInvite, onChangeRole, onRemove }: {
  members: Member[]
  currentUserId: string
  loading?: boolean
  /** Reject with a readable reason on failure. */
  onInvite: (email: string, role: Role) => Promise<void>
  onChangeRole: (id: string, role: Role) => Promise<void>
  onRemove: (id: string) => Promise<void>
}) {
  const [inviteOpen, setInviteOpen] = React.useState(false)
  const [email, setEmail] = React.useState("")
  const [inviteRole, setInviteRole] = React.useState<Role>("Member")
  const [sending, setSending] = React.useState(false)
  const [removing, setRemoving] = React.useState<Member | null>(null)

  // The last Owner is protected: no demotion, no removal.
  const owners = members.filter((m) => m.role === "Owner" && !m.pending)
  const lastOwner = owners.length === 1 ? owners[0] : null

  const fail = (heading: string, e: unknown) =>
    toast({ variant: "danger", title: heading, description: e instanceof Error ? e.message : "Try again." })

  const invite = async () => {
    setSending(true)
    try {
      await onInvite(email, inviteRole)
      setInviteOpen(false)
      setEmail("")
    } catch (e) {
      fail("Invite not sent", e)
    } finally {
      setSending(false)
    }
  }

  const changeRole = async (m: Member, role: Role) => {
    try {
      await onChangeRole(m.id, role)
      toast({ variant: "success", title: "Role updated", description: `${m.name} is now ${role}.` })
    } catch (e) {
      fail("Role not changed", e)
    }
  }

  const remove = async () => {
    if (!removing) return
    try {
      await onRemove(removing.id)
      setRemoving(null)
    } catch (e) {
      fail("Member not removed", e)
    }
  }

  return (
    <div style={{ display: "grid", gap: "var(--atlas-spacing-4)", maxInlineSize: "48rem" }}>
      <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", justifyContent: "space-between", gap: "var(--atlas-spacing-4)" }}>
        <h1 style={title}>Members</h1>
        <Button variant="primary" onClick={() => setInviteOpen(true)}>Invite member</Button>
      </div>

      {lastOwner && (
        <Alert
          variant="info"
          title={`${lastOwner.name} is the only Owner`}
          description={`Make another member an Owner before changing this role or removing ${firstName(lastOwner.name)}.`}
        />
      )}

      <Card variant="outlined">
        <CardHeader><CardTitle>Members</CardTitle></CardHeader>
        <CardContent>
          {loading ? (
            <div role="status" aria-label="Loading members" style={{ display: "grid", gap: "var(--atlas-spacing-4)" }}>
              <Skeleton />
              <Skeleton />
              <Skeleton />
              <Skeleton />
            </div>
          ) : (
            <Table aria-label="Members">
              <TableHeader>
                <TableRow>
                  <TableHead>Member</TableHead>
                  <TableHead>Role</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead><span style={{ position: "absolute", inlineSize: 1, blockSize: 1, overflow: "hidden", clipPath: "inset(50%)" }}>Actions</span></TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {members.map((m) => {
                  const protectedRow = m.id === lastOwner?.id
                  return (
                    <TableRow key={m.id}>
                      <TableCell>
                        <span style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-3)" }}>
                          <Avatar size="md" initials={initialsOf(m.name)} alt="" />
                          <span style={{ display: "grid" }}>
                            <span>{m.name}{m.id === currentUserId ? " (You)" : ""}</span>
                            <span style={muted}>{m.email}</span>
                          </span>
                        </span>
                      </TableCell>
                      <TableCell>
                        {m.pending ? (
                          <span style={muted}>Invited as {m.role}</span>
                        ) : (
                          <Select value={m.role} disabled={protectedRow} onValueChange={(r) => changeRole(m, r as Role)}>
                            <SelectTrigger size="sm" aria-label={`Role for ${m.name}`} aria-describedby={protectedRow ? "last-owner-reason" : undefined}>
                              <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                              {ROLES.map((r) => <SelectItem key={r} value={r}>{r}</SelectItem>)}
                            </SelectContent>
                          </Select>
                        )}
                      </TableCell>
                      <TableCell>
                        <Badge variant={m.pending ? "warning" : "success"} size="md">{m.pending ? "Pending" : "Active"}</Badge>
                      </TableCell>
                      <TableCell align="end">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm" iconOnly aria-label={`Actions for ${m.name}`} disabled={protectedRow} aria-describedby={protectedRow ? "last-owner-reason" : undefined}>
                              <MoreHorizontal aria-hidden />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent>
                            {m.pending && <DropdownMenuItem>Resend invite</DropdownMenuItem>}
                            <DropdownMenuItem destructive onSelect={() => setRemoving(m)}>
                              {m.pending ? "Revoke invite" : "Remove from workspace"}
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
      {lastOwner && (
        <span id="last-owner-reason" style={{ position: "absolute", inlineSize: 1, blockSize: 1, overflow: "hidden", clipPath: "inset(50%)" }}>
          {lastOwner.name} is the only Owner. Make another member an Owner first.
        </span>
      )}

      <Dialog open={inviteOpen} onOpenChange={setInviteOpen}>
        <DialogContent size="md">
          <DialogHeader><DialogTitle>Invite member</DialogTitle></DialogHeader>
          <DialogBody>
            <DialogDescription>
              They will get an email with a link to join. Owners can manage billing; Admins can manage members; Members can edit content.
            </DialogDescription>
            <Field label="Email address" required>
              {(control) => <Input {...control} type="email" placeholder="name@company.com" value={email} onChange={(e) => setEmail(e.target.value)} />}
            </Field>
            <Field label="Role" required>
              {(control) => (
                <Select value={inviteRole} onValueChange={(r) => setInviteRole(r as Role)}>
                  <SelectTrigger id={control.id} aria-describedby={control["aria-describedby"]}><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {ROLES.map((r) => <SelectItem key={r} value={r}>{r}</SelectItem>)}
                  </SelectContent>
                </Select>
              )}
            </Field>
          </DialogBody>
          <DialogFooter>
            <DialogClose><Button variant="ghost">Cancel</Button></DialogClose>
            <Button variant="primary" loading={sending} disabled={!email.trim()} onClick={invite}>Send invite</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <AlertDialog open={removing !== null} onOpenChange={(o) => { if (!o) setRemoving(null) }}>
        <AlertDialogContent variant="destructive">
          <AlertDialogTitle>Remove {removing?.name}?</AlertDialogTitle>
          <AlertDialogDescription>
            {removing && firstName(removing.name)} loses access to this workspace and its projects immediately. Their work stays. You can invite them again later.
          </AlertDialogDescription>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={remove}>Remove {removing && firstName(removing.name)}</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

